PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, provider TEXT NOT NULL, provider_subject TEXT NOT NULL, email TEXT NOT NULL, name TEXT NOT NULL, picture_url TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(provider,provider_subject));
CREATE INDEX users_email ON users(email);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE oauth_states (state_hash TEXT PRIMARY KEY,mode TEXT NOT NULL,redirect TEXT NOT NULL DEFAULT '/',cli_redirect TEXT,cli_state TEXT,code_challenge TEXT,binding_hash TEXT,expires_at INTEGER NOT NULL);
CREATE TABLE cli_codes (code_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),code_challenge TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE cli_credentials (id TEXT PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,created_at TEXT NOT NULL,last_used_at TEXT,revoked_at TEXT);
CREATE INDEX credentials_user ON cli_credentials(user_id);
CREATE TABLE documents (id TEXT PRIMARY KEY,title TEXT NOT NULL,owner_user_id TEXT NOT NULL REFERENCES users(id),current_version_id TEXT,updated_at TEXT NOT NULL,access_revision INTEGER NOT NULL DEFAULT 0,deleted_at TEXT);
CREATE INDEX documents_owner ON documents(owner_user_id,deleted_at,updated_at);
CREATE TABLE versions (id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),number INTEGER NOT NULL,base_version_id TEXT,object_key TEXT UNIQUE NOT NULL,sha256 TEXT NOT NULL,byte_length INTEGER NOT NULL,change_summary TEXT NOT NULL DEFAULT '',created_by_user_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(document_id,number));
CREATE INDEX versions_document ON versions(document_id,number);
CREATE TABLE document_grants (id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),principal_type TEXT NOT NULL CHECK(principal_type IN ('user','anyone')),principal_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('viewer','commenter','editor')),granted_by_user_id TEXT NOT NULL REFERENCES users(id),UNIQUE(document_id,principal_type,principal_id));
CREATE INDEX grants_actor ON document_grants(principal_type,principal_id,document_id);
CREATE TABLE comments (id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),created_on_version_id TEXT NOT NULL REFERENCES versions(id),author_user_id TEXT NOT NULL REFERENCES users(id),parent_comment_id TEXT REFERENCES comments(id),root_comment_id TEXT REFERENCES comments(id),body TEXT NOT NULL,anchor_json TEXT,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,resolved_at TEXT,deleted_at TEXT);
CREATE INDEX comments_document ON comments(document_id,deleted_at,created_at);
CREATE TABLE comment_mentions (comment_id TEXT NOT NULL REFERENCES comments(id),principal_type TEXT NOT NULL,principal_id TEXT NOT NULL,offset INTEGER NOT NULL,length INTEGER NOT NULL,PRIMARY KEY(comment_id,offset));
CREATE TABLE comment_reactions (comment_id TEXT NOT NULL REFERENCES comments(id),user_id TEXT NOT NULL REFERENCES users(id),emoji TEXT NOT NULL,PRIMARY KEY(comment_id,user_id,emoji));
CREATE TABLE pins (user_id TEXT NOT NULL REFERENCES users(id),resource_type TEXT NOT NULL CHECK(resource_type='document'),resource_id TEXT NOT NULL REFERENCES documents(id),PRIMARY KEY(user_id,resource_type,resource_id));
CREATE TABLE document_kv (document_id TEXT NOT NULL REFERENCES documents(id),key TEXT NOT NULL,value_json TEXT NOT NULL,revision INTEGER NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(document_id,key));
CREATE TABLE document_revisions (document_id TEXT PRIMARY KEY REFERENCES documents(id),revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE orphan_objects (object_key TEXT PRIMARY KEY,created_at TEXT NOT NULL);
